import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'ok' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  ok: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышена', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас', quotaPercent: 42, status: 'ok' },
  { id: 'p2', name: 'Периметр', quotaPercent: 88, status: 'warning' },
  { id: 'p3', name: 'Орбита', quotaPercent: 104, status: 'over' },
  { id: 'p4', name: 'Резонанс', quotaPercent: 15, status: 'ok' },
  { id: 'p5', name: 'Маяк', quotaPercent: 67, status: 'ok' },
  { id: 'p6', name: 'Горизонт', quotaPercent: 91, status: 'warning' },
  { id: 'p7', name: 'Квант', quotaPercent: 112, status: 'over' },
  { id: 'p8', name: 'Импульс', quotaPercent: 30, status: 'ok' },
  { id: 'p9', name: 'Вектор', quotaPercent: 76, status: 'warning' },
  { id: 'p10', name: 'Каскад', quotaPercent: 5, status: 'ok' },
  { id: 'p11', name: 'Прибой', quotaPercent: 99, status: 'over' },
  { id: 'p12', name: 'Ясень', quotaPercent: 54, status: 'ok' },
];

const PAGE_SIZE = 5;
const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((project) => activeStatuses.includes(project.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '640px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {ALL_STATUSES.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length > 0 ? (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                  }}
                >
                  {project.name}
                </span>
                <JxProgressCircle value={Math.min(project.quotaPercent, 100)} showValue />
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      ) : (
        <JxEmptyState
          title="Проекты не найдены"
          message="Ни один проект не подходит под выбранные фильтры статуса."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      )}
    </div>
  );
}

